<template><view class="page safe-bottom"><view class="status-banner" :class="`status-${order.orderStatus}`"><text class="status-title">{{ statusText(order.orderStatus) }}</text><text class="status-desc">{{ statusDesc(order.orderStatus) }}</text></view><view class="detail-card surface"><view class="row"><text>服务项目</text><text class="value">{{ order.serviceName || '家政服务' }}</text></view><view class="row"><text>预约时间</text><text class="value">{{ order.appointmentDate || '-' }} {{ order.slotName || '' }}</text></view><view class="row"><text>服务地址</text><text class="value">{{ order.address || '-' }}</text></view><view class="row"><text>联系电话</text><text class="value">{{ order.phone || '-' }}</text></view><view class="row"><text>订单金额</text><text class="amount">¥{{ order.amount || 0 }}</text></view></view><button v-if="String(order.orderStatus) === '2'" class="primary-button" @click="review">评价服务</button><button v-if="String(order.orderStatus) === '0'" class="cancel-button" @click="cancel">取消预约</button></view></template>
<script setup>
import { onMounted, reactive } from 'vue'; import { cancelOrder, listOrders } from '@/api/service'; import { useAuthStore } from '@/stores/auth'; const authStore = useAuthStore(); const order = reactive({}); onMounted(async () => { if (!authStore.isLoggedIn) return uni.redirectTo({ url: '/pages/login/index?redirect=/pages/orders/index' }); const id = getCurrentPages().at(-1)?.options?.id; try { const response = await listOrders({ orderId: id, pageSize: 1 }); const item = response.rows?.[0] || response.data?.rows?.[0]; if (item) Object.assign(order, item) } catch (e) { uni.showToast({ title: e.message || '订单加载失败', icon: 'none' }) } }); function statusText (value) { return ({ 0: '待确认', 1: '服务中', 2: '已完成', 3: '已取消' })[value] || '处理中' }; function statusDesc (value) { return ({ 0: '我们会尽快确认您的预约', 1: '服务人员将按约定时间上门', 2: '感谢您的信任，期待再次为您服务', 3: '该预约已取消' })[value] || '' }; async function cancel () { try { await cancelOrder(order.orderId); order.orderStatus = '3'; uni.showToast({ title: '已取消', icon: 'success' }) } catch (e) { uni.showToast({ title: e.message || '操作失败', icon: 'none' }) } }; function review () { uni.navigateTo({ url: `/pages/review/index?id=${order.orderId}` }) }
</script><style lang="scss" scoped>
.status-banner{margin:-32rpx -32rpx 22rpx;padding:54rpx 34rpx;color:#fff;background:$app-primary}.status-2{background:#20a777}.status-3{background:#8995a8}.status-title{display:block;font-size:40rpx;font-weight:800}.status-desc{display:block;margin-top:12rpx;opacity:.85;font-size:25rpx}.detail-card{padding:8rpx 28rpx}.row{display:flex;justify-content:space-between;padding:28rpx 0;color:$app-muted;font-size:26rpx;border-bottom:1rpx solid $app-border}.row:last-child{border:0}.value{max-width:68%;color:$app-text;text-align:right}.amount{color:$app-accent;font-size:32rpx;font-weight:700}.primary-button{width:100%;margin-top:34rpx}.cancel-button{width:100%;margin-top:18rpx;color:#d65c58;background:#fff;border:1rpx solid #f2cccc;line-height:92rpx;border-radius:16rpx}
</style>
